"""Write build/fn_paths.vh with absolute asset paths (PDS needs absolute paths)."""
from pathlib import Path
from relocate_pose_paths import relocate

relocate()

ROOT = Path(__file__).resolve().parents[1]
B = (ROOT / "build").as_posix()
prog = f"{B}/program.hex"
lines = [
    "// Generated by tools/gen_paths.py",
    f'`define FN_SPRITE_HEX "{B}/sprites.hex"',
    f'`define FN_FONT_HEX "{B}/font.hex"',
    f'`define FN_PAL_HEX "{B}/palette.hex"',
    f'`define FN_PROGRAM_HEX "{prog}"',
    f"`define FN_PROGRAM_HEX_BITS {8 * len(prog)}",
    "",
]
(ROOT / "build" / "fn_paths.vh").write_text("\n".join(lines), encoding="ascii")
print("\n".join(lines))
